import json,os,subprocess,sys,time
from pathlib import Path
root=Path('/tmp/style-m3-a9-20261017');name=sys.argv[1];cmd=sys.argv[2:];env=os.environ.copy()
for key in ['CODEX_HOME','CODEX_SANDBOX','STYLE_HOME','CLAUDE_CONFIG_DIR','CLAUDE_CODE_CONFIG_DIR','CLAUDE_CODE_EFFORT_LEVEL','CLAUDE_EFFORT','PLUGIN_ROOT','STYLE_PERF','STYLE_PERF_OUTPUT','STYLE_M3_A6_RECORD','STYLE_UPDATE_GOLDENS','STYLE_REFRESH_HELPER','STYLE_REFRESH_TURN','STYLE_REFRESH_WORKER']:env.pop(key,None)
for key,value in {'GOPATH':'gopath','GOMODCACHE':'modcache','GOCACHE':'gocache'}.items():env[key]=str(Path('/tmp/style-m3-project-20261017')/value)
env['GOPROXY']='off';env['GOFLAGS']='-mod=readonly';env['GOWORK']='off';start=time.time()
with (root/(name+'.log')).open('wb') as f:p=subprocess.run(cmd,env=env,stdout=f,stderr=subprocess.STDOUT)
result={'command':cmd,'exit_code':p.returncode,'seconds':round(time.time()-start,3),'environment':{key:env[key] for key in ['GOPATH','GOMODCACHE','GOCACHE','GOPROXY','GOFLAGS','GOWORK']}}
(root/(name+'.json')).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
if p.returncode:
 lines=(root/(name+'.log')).read_text().splitlines();events=[]
 for line in lines:
  try:events.append(json.loads(line))
  except:pass
 failed=[v.get('Test') for v in events if v.get('Action')=='fail' and v.get('Test')]
 if failed:
  for test in failed:print(test, ''.join(v.get('Output','') for v in events if v.get('Test')==test)[-2200:])
 else: print('\n'.join(lines[-35:]))
sys.exit(p.returncode)
